query LinearSearchIssues($filter: IssueFilter, $first: Int!, $after: String, $orderBy: PaginationOrderBy, $includeArchived: Boolean) {
  issues(filter: $filter, first: $first, after: $after, orderBy: $orderBy, includeArchived: $includeArchived) {
    nodes { id identifier title url priority dueDate labelIds createdAt updatedAt archivedAt
      team { id key name } state { id name type } assignee { id } }
    pageInfo { hasNextPage endCursor }
  }
}

